create function public.englishsuccess_language() returns jsonb
language sql stable security invoker set search_path='' as $$
  select jsonb_build_object('version',1,'words',
    coalesce(jsonb_agg(to_jsonb(w) order by word),'[]'::jsonb))
  from public.englishsuccess_words w;
$$;
revoke all on function public.englishsuccess_language() from public;
grant execute on function public.englishsuccess_language() to anon, authenticated;
commit;
